using BabyRoutine.Domain.Common;
using BabyRoutine.Domain.Exceptions;

namespace BabyRoutine.Domain.Events;

/// <summary>
/// A logged baby event. The id is generated by the client so offline writes can be replayed idempotently.
/// <see cref="EndedAt"/> is <c>null</c> while the event is running. Deletes are soft (<see cref="DeletedAt"/>)
/// and every change bumps <see cref="UpdatedAt"/> so delta sync picks it up. All timestamps are UTC.
/// </summary>
public sealed class Event
{
    public const int NotesMaxLength = 2000;

    private Event()
    {
    }

    private Event(Guid id, Guid babyId, Guid typeId, Guid createdBy, DateTimeOffset createdAt)
    {
        Id = id;
        BabyId = babyId;
        TypeId = typeId;
        CreatedBy = createdBy;
        CreatedAt = createdAt;
        UpdatedAt = createdAt;
    }

    public Guid Id { get; private set; }

    public Guid BabyId { get; private set; }

    public Guid TypeId { get; private set; }

    public DateTimeOffset StartedAt { get; private set; }

    public DateTimeOffset? EndedAt { get; private set; }

    public EventPayload Payload { get; private set; } = EventPayload.Empty;

    public string? Notes { get; private set; }

    public Guid CreatedBy { get; private set; }

    public DateTimeOffset CreatedAt { get; private set; }

    public DateTimeOffset UpdatedAt { get; private set; }

    public DateTimeOffset? DeletedAt { get; private set; }

    public bool IsDeleted => DeletedAt is not null;

    public bool IsRunning => EndedAt is null && !IsDeleted;

    public TimeSpan? Duration => EndedAt - StartedAt;

    public static Event Create(
        Guid id,
        Guid babyId,
        Guid typeId,
        Guid createdBy,
        DateTimeOffset startedAt,
        DateTimeOffset? endedAt,
        EventPayload payload,
        string? notes,
        DateTimeOffset now)
    {
        var created = new Event(
            Ids.Required(id, nameof(id)),
            Ids.Required(babyId, nameof(babyId)),
            Ids.Required(typeId, nameof(typeId)),
            Ids.Required(createdBy, nameof(createdBy)),
            UtcTime.Normalize(now));
        created.ApplyDetails(startedAt, endedAt, payload, notes);
        return created;
    }

    /// <summary>Replaces the editable details, as for an idempotent upsert of an existing event.</summary>
    public void Edit(Guid typeId, DateTimeOffset startedAt, DateTimeOffset? endedAt, EventPayload payload, string? notes, DateTimeOffset now)
    {
        EnsureNotDeleted();
        Ids.Required(typeId, nameof(typeId));
        ApplyDetails(startedAt, endedAt, payload, notes);
        TypeId = typeId;
        Touch(now);
    }

    /// <summary>Ends a running event.</summary>
    public void Stop(DateTimeOffset endedAt, DateTimeOffset now)
    {
        EnsureNotDeleted();
        EnsureRunning();
        EndedAt = EnsureValidRange(StartedAt, UtcTime.Normalize(endedAt));
        Touch(now);
    }

    /// <summary>Marks the event deleted. Repeating it is a no-op so retried deletes stay idempotent.</summary>
    public void SoftDelete(DateTimeOffset now)
    {
        if (IsDeleted)
        {
            return;
        }

        DeletedAt = UtcTime.Normalize(now);
        UpdatedAt = DeletedAt.Value;
    }

    private void ApplyDetails(DateTimeOffset startedAt, DateTimeOffset? endedAt, EventPayload payload, string? notes)
    {
        var normalizedStart = UtcTime.Normalize(startedAt);
        var normalizedEnd = EnsureValidRange(normalizedStart, UtcTime.Normalize(endedAt));
        var validatedNotes = Text.Optional(notes, nameof(Notes), NotesMaxLength);
        StartedAt = normalizedStart;
        EndedAt = normalizedEnd;
        Payload = payload;
        Notes = validatedNotes;
    }

    private void Touch(DateTimeOffset now) => UpdatedAt = UtcTime.Normalize(now);

    private void EnsureNotDeleted()
    {
        if (IsDeleted)
        {
            throw new EventDeletedException(Id);
        }
    }

    private void EnsureRunning()
    {
        if (EndedAt is not null)
        {
            throw new EventAlreadyStoppedException(Id);
        }
    }

    private static DateTimeOffset? EnsureValidRange(DateTimeOffset startedAt, DateTimeOffset? endedAt) =>
        endedAt is null || endedAt.Value >= startedAt
            ? endedAt
            : throw new InvalidEventTimeRangeException(startedAt, endedAt.Value);

    private static DateTimeOffset EnsureValidRange(DateTimeOffset startedAt, DateTimeOffset endedAt) =>
        endedAt >= startedAt ? endedAt : throw new InvalidEventTimeRangeException(startedAt, endedAt);
}
